class BusMeter : public juce::Component,public juce::SettableTooltipClient {
public:
    float level=0;const juce::Slider* scale=nullptr;
    juce::String valueText()const{return level>.00001f?juce::String(juce::Decibels::gainToDecibels(level,-60.f),1)+" dB":tr("Silence");}
    void paint(juce::Graphics& g)override{
        auto r=getLocalBounds().toFloat().reduced(1);g.setColour(StudioStyle::lcd);g.fillRoundedRectangle(r,2);g.setColour(StudioStyle::line);g.drawRoundedRectangle(r,2,1);
        if(level>.001f&&scale){const float db=std::clamp(juce::Decibels::gainToDecibels(level,-60.f),-60.f,6.f);const float y=std::clamp(scale->getY()+scale->getPositionOfValue(db)-getY(),r.getY(),r.getBottom());g.setColour(StudioStyle::accent);g.fillRect(r.withTop(y).reduced(2,0));}
        g.setColour(StudioStyle::lcd.withAlpha(.5f));for(float y=r.getY()+3;y<r.getBottom();y+=4)g.drawHorizontalLine((int)y,r.getX()+2,r.getRight()-2);
    }
};
const char* busTitle(int bus){return bus==0?"GROUP A":bus==1?"GROUP B":bus==2?"REVERB":"DELAY";}

